[{"id":"ai-dialect-17","url":"https://www.appenzell.ch/de/kultur-und-braeuche/innerrhoder-dialekt.html","title":"Innerrhoden · Pequeño vocabulario de dialecto","authority":"Appenzellerland Tourismus AI","checked_at":"2026-11-17","locator":"Tabla dialecto–alemán estándar"}],"source_url":"https://www.appenzell.ch/de/kultur-und-braeuche/innerrhoder-dialekt.html","source_title":"Innerrhoden · Pequeño vocabulario de dialecto","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_review_at":"2027-11-17","concept_id":"AI:fenz","status":"published","editorial_difficulty":"media","correct_index":3,"editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["10d08feeda67b0cd9506ccf1372f14df"]},{"question":{"id":"szx-ai-bordado-ingresos","collection":"suizamente-integration-1350-v1","territory":"AI","scope":"canton","canton":"AI","topic":"cultura","category":"sociedad","difficulty":3,"language":"es","game_type":"choice","prompt":"Además de decorar prendas, ¿qué papel histórico tuvo el bordado a mano en Innerrhoden?","options":["Aportar ingresos al sustento de muchas familias","Financiar exclusivamente edificios del cantón","Sustituir el trabajo agrícola por obligación legal","Servir solo para vestir a la familia sin venta exterior"],"explanation":"La historia del oficio incluye trabajo doméstico, comercio y exportación.","sources":[{"id":"ai-embroidery-17","url":"https://www.appenzell.ch/de/kultur-und-braeuche/kunsthandwerk/handstickerei.html","title":"Innerrhoden · Bordado a mano","authority":"Appenzellerland Tourismus AI","checked_at":"2026-11-17","locator":"Historia, trabajo doméstico, materiales"}],"source_url":"https://www.appenzell.ch/de/kultur-und-braeuche/kunsthandwerk/handstickerei.html","source_title":"Innerrhoden · Bordado a mano","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_re