-ryys-und-boor","title":"Uri · Ryys und Boor","authority":"Uri Tourismus","checked_at":"2026-11-17","locator":"Introducción y contraste con ingredientes del folleto, p.22"}],"source_url":"https://uri.swiss/essen-und-trinken/regionale-rezepte/rezept-ryys-und-boor","source_title":"Uri · Ryys und Boor","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_review_at":"2027-11-17","concept_id":"UR:ryys-boor","status":"published","editorial_difficulty":"facil","correct_index":3},"known":["a0845143878ba50c6dd0643e5fd03f39"]},{"question":{"id":"szx-ur-katzenmusik-contexto","collection":"suizamente-integration-1350-v1","territory":"UR","scope":"canton","canton":"UR","topic":"cultura","category":"sociedad","difficulty":1,"language":"es","game_type":"choice","prompt":"En Uri te invitan a tocar Katzenmusik. ¿En qué celebración encaja esta marcha con instrumentos de viento y percusión?","options":["En la Fasnacht, el carnaval","En la Alpabfahrt","En una Landsgemeinde","En el Zibelemärit"],"explanation":"Cada localidad puede interpretar la marcha con sus particularidades.","sources":[{"id":"ur-facts-17","url":"https://www.ur.ch/_docn/410917/Zahlen_und_Fakten_Uri.pdf","title":"Uri · Patrimonio, dialecto y pasos alpinos","authority":"Uri Tourismus, folleto alojado por el cantón","checked_at":"2026-11-17","locator":"Páginas impresas 3–5, 11–12, 14–19 y 22–23"}],"source_url":"https://www.ur.ch/_docn/410917/Zahlen_und_Fakten_Uri.pdf","source_title":"Uri · Patrimonio, dialecto y pasos alpinos","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_review_at":"2027-11-17","concept_id":"UR:katzenmusik-contexto","status":"published","editorial_difficulty":"facil","correct_index":0,"editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["ffabb1e00ada1a18143921a31d59df7a"]},{"question":{"id":"szx-ur-wildheue