1-17","concept_id":"OW:ranft-nombre","status":"published","editorial_difficulty":"facil","correct_index":2},"known":["777b5bfc7c09e435df17230a0c5fe560"]},{"question":{"id":"szx-ow-langis-paisaje","collection":"suizamente-integration-1350-v1","territory":"OW","scope":"canton","canton":"OW","topic":"naturaleza","category":"sociedad","difficulty":1,"language":"es","game_type":"choice","prompt":"¿Qué paisaje caracteriza Langis-Glaubenberg, además de bosques y pastos?","options":["Grandes viñedos escalonados","Olivares de clima mediterráneo","Campos de sal","Turberas y humedales"],"explanation":"Moorlandschaft significa paisaje de turberas; es un entorno sensible, no un parque urbano cualquiera.","sources":[{"id":"ow-landscape-17","url":"https://www.obwalden-tourismus.ch/de/anreise/","title":"Obwalden · Paisajes y patrimonio","authority":"Obwalden Tourismus","checked_at":"2026-11-17","locator":"Gemeinden & Freizeitregionen: Langis, Kerns, Giswil y Lungern"}],"source_url":"https://www.obwalden-tourismus.ch/de/anreise/","source_title":"Obwalden · Paisajes y patrimonio","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_review_at":"2027-11-17","concept_id":"OW:langis-paisaje","status":"published","editorial_difficulty":"facil","correct_index":3,"editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["1df06c462411608544a726ffc52871fa"]},{"question":{"id":"szx-ow-stokalp-destino","collection":"suizamente-integration-1350-v1","territory":"OW","scope":"canton","canton":"OW","topic":"movilidad","category":"sociedad","difficulty":3,"language":"es","game_type":"choice","prompt":"La góndola que sale de Stöckalp te permite subir a…","options":["Melchsee-Frutt","Jungfraujoch","Montreux","Gornergrat"],"explanation":"Es una conexión de la zona de Kerns. Consulta la explotación y el tiempo antes de viajar.","sources":[{"id":"ow-landscape-17","url":"https://www.obwalden-tourismus.ch/de/anreise/","title":"Obwalden · Paisajes y patrimonio","authority":"Obwalden Tourismus","checked_at":"2026-11-17","locator":"Gemeinden & Freizeitregionen: Langis, Kerns, Giswil y Lungern"}],"source_url":"https://www.obwalden-tourismus.ch/de/anreise/","source_title":"Obwalden · Paisajes y patrimonio","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":true,"next_review_at":"2027-02-17","concept_id":"OW:stokalp-destino","status":"published","editorial_difficulty":"media","correct_index":0},"known":["8803a95ac27f333483a8f61882d241c8"]},{"question":{"id":"szx-ow-brunig-lago","collection":"suizamente-integration-1350-v1","territory":"OW","scope":"canton","canton":"OW","topic":"naturaleza","category":"sociedad","difficulty":1,"language":"es","game_type":"choice","prompt":"Vas hacia el Brünig y paras en Lungern. ¿Qué lago tienes al lado?","options":["Lac Léman","Lungernsee","Bodensee","Lago Maggiore"],"explanation":"Lungern está al pie del Brünig y junto al lago de su nombre.","sources":[{"id":"ow-places-17","url":"https://www.ow.ch/gemeindenmain","title":"Obwalden · Municipios y geografía","authority":"Kanton Obwalden","checked_at":"2026-11-17","locator":"Fichas de los siete municipios"}],"source_url":"https://www.ow.ch/gemeindenmain","source_title":"Obwalden · Municipios y geografía","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_review_at":"2027-11-17","concept_id":"OW:brunig-lago","status":"published","editorial_difficulty":"facil","correct_index":1},"known":["55979b7ee37c4c1efbe2e3667c518e00"]},{"question":{"id":"szx-ow-treffpunkt-candidatura","collection":"suizamente-integration-1350-v1","territory":"OW","scope":"canton","canton":"OW","topic":"tramites","category":"trabajo","difficulty":1,"language":"es","game_type":"choice","prompt":"Quieres preparar tu candidatura a un empleo en Obwalden. ¿Qué ayuda ofrece Treffpunkt B