ority":"Fachstelle Gesellschaftsfragen Obwalden","checked_at":"2026-11-17","locator":"Integrationsangebote, Treffpunkt Bewerbung, Offene Tür, Femmes-Tische y discriminación"}],"source_url":"https://integration.ow.ch/integrationsangebote/","source_title":"Obwalden · Orientación y encuentros","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":true,"next_review_at":"2027-02-17","concept_id":"OW:offene-tur-objetivo","status":"published","editorial_difficulty":"facil","correct_index":1,"editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["776985904a2ce1d6a1e62a7d1a5adad1"]},{"question":{"id":"szx-ow-femmes-temas","collection":"suizamente-integration-1350-v1","territory":"OW","scope":"canton","canton":"OW","topic":"convivencia","category":"vivienda","difficulty":3,"language":"es","game_type":"multi","prompt":"¿Qué temas se mencionan para las conversaciones Femmes-Tische en Obwalden?","options":["Salud","Presupuesto familiar","Crianza","Concesión de pasaportes"],"explanation":"Son encuentros de intercambio, también en la propia lengua; no trámites de nacionalidad.","sources":[{"id":"ow-orientation-17","url":"https://integration.ow.ch/integrationsangebote/","title":"Obwalden · Orientación y encuentros","authority":"Fachstelle Gesellschaftsfragen Obwalden","checked_at":"2026-11-17","locator":"Integrationsangebote, Treffpunkt Bewerbung, Offene Tür, Femmes-Tische y discriminación"}],"source_url":"https://integration.ow.ch/integrationsangebote/","source_title":"Obwalden · Orientación y encuentros","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":true,"next_review_at":"2027-02-17","concept_id":"OW:femmes-temas","status":"published","editorial_difficulty":"media","game_only":true,"correct_indices":[0,1,2],"correct_index":0},"known":["143b212516dd2f7f370b4ef8036fb72f"]},{"question":{"id":"szx-ow-apoyo-aleman-c